theme.css:
#wemd{color:#1a2332;background-color:#f8f9fc;font-family:'Inter', -apple-system, 'Segoe UI', 'Noto Sans SC', sans-serif;font-size:15px;line-height:1.75;letter-spacing:-0.01em;text-align:left;padding:32px 24px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.2em;text-indent:0}
#wemd h1{font-size:26px;font-weight:800;color:$colors.accent;margin-top:2em;margin-bottom:1em;text-align:left;border-bottom:1px solid $colors.accent;padding-bottom:.4em}
#wemd h2{font-size:21px;font-weight:700;color:$colors.text_primary;margin-top:1.8em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid $colors.border;padding-bottom:.4em}
#wemd h3{font-size:17px;font-weight:600;color:$colors.accent;margin-top:1.5em;margin-bottom:0.6em}
#wemd h3::before{content:"· ";color:#1e3a5f}
#wemd h4{font-size:15px;font-weight:600;color:$colors.text_secondary;margin-top:1.2em;margin-bottom:0.5em}
#wemd blockquote{border-left:4px solid $colors.quote_border;background:$colors.quote_background;padding:14px 20px;color:$colors.text_secondary;font-style:normal;margin:1.2em 0}
#wemd code{background-color:$colors.code_background;color:#1e3a5f;padding:2px 6px;border-radius:4px;font-size:0.9em;font-family:'Fira Code', monospace}
#wemd pre{background:#1a2332;border-radius:6px;padding:18px 22px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.border;padding:10px 14px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:$colors.accent}
#wemd hr{border:0;border-top:1px solid $colors.border;margin:2em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:6px}
#wemd figcaption{font-size:13px;color:$colors.text_secondary;text-align:center}
#wemd a{color:$colors.link_color;text-decoration:none}
#wemd strong{color:#1e3a5f;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:2px 6px;border-radius:4px}
